fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo and choose 'Credentials', then open the 'Types' section. Pages can take 10-30s to load — wait, don't navigate away. Types are grouped under category headers in the left list. Click a credential type. Verify a detail panel opens on the right showing the type's stats (Credentials / Active counts) and a 'Field Schema' section listing the type's fields with badges (data type, plus 'Secret' / 'Required' where applicable). If no types exist, a valid empty state is acceptable success.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
